void AudienceSharing::registerRoutes(httplib::Server& svr, std::shared_ptr<AuthenticationManager> auth)
{
    svr.Get("/ad_accounts/{ad_account_id}/audiences/shared/accounts", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdaudiencessharedaccountsGetRequest(req, res, auth);
    });
    svr.Get("/businesses/{business_id}/audiences/shared/accounts", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdaudiencessharedaccountsGetRequest(req, res, auth);
    });
    svr.Get("/businesses/{business_id}/audiences", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdaudiencesGetRequest(req, res, auth);
    });
    svr.Patch("/ad_accounts/{ad_account_id}/audiences/ad_accounts/shared", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdaudiencesadAccountssharedPatchRequest(req, res, auth);
    });
    svr.Patch("/ad_accounts/{ad_account_id}/audiences/businesses/shared", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleAdAccountsadAccountIdaudiencesbusinessessharedPatchRequest(req, res, auth);
    });
    svr.Patch("/businesses/{business_id}/audiences/ad_accounts/shared", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdaudiencesadAccountssharedPatchRequest(req, res, auth);
    });
    svr.Patch("/businesses/{business_id}/audiences/businesses/shared", [this, auth]([[maybe_unused]] const httplib::Request& req, httplib::Response& res)
    {
        handleBusinessesbusinessIdaudiencesbusinessessharedPatchRequest(req, res, auth);
    });
}

